({
  _initData() {
    if (!this.data || typeof this.data !== 'object') {
      this.data = {
        entries: {},
        stats: {
          hits: 0,
          misses: 0,
          sets: 0,
          prunes: 0,
          expiredCount: 0
        }
      };
    }
    if (!this.data.entries || typeof this.data.entries !== 'object') {
      this.data.entries = {};
    }
    if (!this.data.stats || typeof this.data.stats !== 'object') {
      this.data.stats = {
        hits: 0,
        misses: 0,
        sets: 0,
        prunes: 0,
        expiredCount: 0
      };
    }
  },

  _checkInvariants() {
    this.invariant(Boolean(this.data && typeof this.data === 'object'), "this.data must be an object");
    this.invariant(Boolean(this.data.entries && typeof this.data.entries === 'object'), "this.data.entries must be an object");
    this.invariant(Boolean(this.data.stats && typeof this.data.stats === 'object'), "this.data.stats must be an object");
    this.invariant(typeof this.data.stats.hits === 'number' && this.data.stats.hits >= 0, "stats.hits must be a non-negative number");
    this.invariant(typeof this.data.stats.misses === 'number' && this.data.stats.misses >= 0, "stats.misses must be a non-negative number");
    this.invariant(typeof this.data.stats.sets === 'number' && this.data.stats.sets >= 0, "stats.sets must be a non-negative number");
    this.invariant(typeof this.data.stats.prunes === 'number' && this.data.stats.prunes >= 0, "stats.prunes must be a non-negative number");
    this.invariant(typeof this.data.stats.expiredCount === 'number' && this.data.stats.expiredCount >= 0, "stats.expiredCount must be a non-negative number");
  },

  init(msg) {
    this._initData();
    this._checkInvariants();
    const result = { ok: true };
    this.ensure(result && result.ok === true, "Initialization must return success status");
    return result;
  },

  set(msg) {
    this.ensure(Boolean(msg && msg.payload && typeof msg.payload === 'object'), "Payload object is required");
    const { key, value, ttlMs } = msg.payload;
    this.ensure(typeof key === 'string' && key.length > 0, "key must be a non-empty string");
    this.ensure(typeof ttlMs === 'number' && ttlMs > 0 && !isNaN(ttlMs), "ttlMs must be a positive number");

    this._initData();
    const now = Date.now();
    const expiresAt = now + ttlMs;

    this.data.entries[key] = {
      value,
      expiresAt,
      createdAt: now,
      ttlMs
    };
    this.data.stats.sets += 1;

    this._checkInvariants();
    if (typeof this.changed === 'function') {
      this.changed('set', { key, expiresAt });
    }

    const result = { ok: true, key, expiresAt };
    this.ensure(Boolean(result && result.ok && this.data.entries[key]), "Entry must be stored in cache");
    return result;
  },

  get(msg) {
    this.ensure(Boolean(msg && msg.payload && typeof msg.payload === 'object'), "Payload object is required");
    const { key } = msg.payload;
    this.ensure(typeof key === 'string' && key.length > 0, "key must be a non-empty string");

    this._initData();
    const now = Date.now();
    const entry = this.data.entries[key];

    let result;
    if (!entry) {
      this.data.stats.misses += 1;
      this._checkInvariants();
      result = { found: false, key, value: null };
    } else if (entry.expiresAt <= now) {
      delete this.data.entries[key];
      this.data.stats.misses += 1;
      this.data.stats.expiredCount += 1;
      this._checkInvariants();
      if (typeof this.changed === 'function') {
        this.changed('expired', { key });
      }
      result = { found: false, key, value: null, expired: true };
    } else {
      this.data.stats.hits += 1;
      this._checkInvariants();
      result = {
        found: true,
        key,
        value: entry.value,
        remainingTtlMs: Math.max(0, entry.expiresAt - now)
      };
    }

    this.ensure(Boolean(result && typeof result.found === 'boolean'), "Result must include found status flag");
    return result;
  },

  pruneExpired(msg) {
    this._initData();
    const now = Date.now();
    let pruned = 0;

    for (const [key, entry] of Object.entries(this.data.entries)) {
      if (entry && typeof entry.expiresAt === 'number' && entry.expiresAt <= now) {
        delete this.data.entries[key];
        pruned += 1;
      }
    }

    this.data.stats.prunes += 1;
    this.data.stats.expiredCount += pruned;
    this._checkInvariants();

    if (pruned > 0 && typeof this.changed === 'function') {
      this.changed('prune', { pruned });
    }

    const remainingSize = Object.keys(this.data.entries).length;
    const result = { ok: true, pruned, remainingSize };
    this.ensure(Boolean(result && typeof result.pruned === 'number' && result.pruned >= 0), "Prune must return a non-negative pruned count");
    return result;
  },

  getStats(msg) {
    this._initData();
    const now = Date.now();
    let activeCount = 0;
    let unprunedExpiredCount = 0;

    for (const entry of Object.values(this.data.entries)) {
      if (entry && typeof entry.expiresAt === 'number' && entry.expiresAt > now) {
        activeCount += 1;
      } else {
        unprunedExpiredCount += 1;
      }
    }

    const stats = {
      hits: this.data.stats.hits,
      misses: this.data.stats.misses,
      sets: this.data.stats.sets,
      prunes: this.data.stats.prunes,
      expiredCount: this.data.stats.expiredCount,
      size: Object.keys(this.data.entries).length,
      activeCount,
      unprunedExpiredCount
    };

    this.ensure(Boolean(stats && typeof stats.size === 'number' && typeof stats.hits === 'number'), "Must return a valid stats payload");
    return stats;
  }
})
